"""Bundled Jinja templates."""
TEMPLATES = {'base.html': '<!DOCTYPE html>\n<html lang="ru">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>{% block title %}Трекер расходов{% endblock %}</title>\n<style>\n  :root {\n    --bg: #0f1117;\n    --card: #171a24;\n    --card-border: #262a38;\n    --text: #eef0f5;\n    --muted: #8b91a7;\n    --accent: #7c5cff;\n    --accent2: #22d3a5;\n    --danger: #ff5c7a;\n    --radius: 16px;\n  }\n  * { box-sizing: border-box; }\n  body {\n    margin: 0;\n    font-family: \'Segoe UI\', system-ui, -apple-system, sans-serif;\n    background: radial-gradient(1200px 600px at 10% -10%, #1c1f2e 0%, var(--bg) 60%);\n    color: var(--text);\n    min-height: 100vh;\n  }\n  .wrap { max-width: 480px; margin: 0 auto; padding: 24px 18px 60px; }\n  .center-wrap { max-width: 380px; margin: 10vh auto; padding: 0 20px; }\n  h1, h2, h3 { margin: 0 0 6px; }\n  .brand {\n    font-weight: 800; font-size: 26px; letter-spacing: -0.5px;\n    background: linear-gradient(90deg, var(--accent), var(--accent2));\n    -webkit-background-clip: text; background-clip: text; color: transparent;\n    text-align: center; margin-bottom: 28px;\n  }\n  .card {\n    background: var(--card);\n    border: 1px solid var(--card-border);\n    border-radius: var(--radius);\n    padding: 20px;\n    margin-bottom: 16px;\n    box-shadow: 0 10px 30px rgba(0,0,0,0.25);\n  }\n  input, select {\n    width: 100%;\n    padding: 12px 14px;\n    border-radius: 10px;\n    border: 1px solid var(--card-border);\n    background: #10131c;\n    color: var(--text);\n    font-size: 15px;\n    margin-bottom: 12px;\n  }\n  input:focus, select:focus { outline: none; border-color: var(--accent); }\n  label { font-size: 13px; color: var(--muted); display: block; margin-bottom: 6px; }\n  button, .btn {\n    width: 100%;\n    padding: 13px;\n    border-radius: 10px;\n    border: none;\n    font-weight: 600;\n    font-size: 15px;\n    cursor: pointer;\n    background: linear-gradient(90deg, var(--accent), #9b7bff);\n    color: white;\n    transition: transform .15s ease, opacity .15s ease;\n  }\n  button:hover, .btn:hover { opacity: 0.92; transform: translateY(-1px); }\n  .btn-secondary { background: #262a38; }\n  .btn-danger { background: transparent; color: var(--danger); border: 1px solid rgba(255,92,122,0.4); font-weight: 500; padding: 6px 10px; width: auto; font-size: 13px; }\n  a { color: var(--accent2); text-decoration: none; }\n  .stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 16px; }\n  .stat { background: var(--card); border: 1px solid var(--card-border); border-radius: 14px; padding: 14px 10px; text-align: center; }\n  .stat .value { font-size: 20px; font-weight: 800; color: var(--accent2); }\n  .stat .label { font-size: 11px; color: var(--muted); margin-top: 4px; }\n  .topbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }\n  .topbar .hi { font-size: 14px; color: var(--muted); }\n  .flash { padding: 10px 14px; border-radius: 10px; margin-bottom: 14px; font-size: 14px; }\n  .flash.success { background: rgba(34,211,165,0.12); color: var(--accent2); border: 1px solid rgba(34,211,165,0.3); }\n  .flash.error { background: rgba(255,92,122,0.12); color: var(--danger); border: 1px solid rgba(255,92,122,0.3); }\n  .expense-row { display: flex; justify-content: space-between; align-items: center; padding: 10px 0; border-bottom: 1px solid var(--card-border); }\n  .expense-row:last-child { border-bottom: none; }\n  .expense-row .info { font-size: 14px; }\n  .expense-row .cat { color: var(--muted); font-size: 12px; }\n  .expense-row .amt { font-weight: 700; }\n  .cat-bar { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; font-size: 13px; }\n  .cat-bar .track { flex: 1; height: 8px; background: #10131c; border-radius: 6px; overflow: hidden; }\n  .cat-bar .fill { height: 100%; background: linear-gradient(90deg, var(--accent), var(--accent2)); }\n  .footer-link { text-align: center; margin-top: 16px; font-size: 14px; color: var(--muted); }\n</style>\n</head>\n<body>\n  <div class="{% block container_class %}wrap{% endblock %}">\n    {% with messages = get_flashed_messages(with_categories=true) %}\n      {% if messages %}\n        {% for category, message in messages %}\n          <div class="flash {{ category }}">{{ message }}</div>\n        {% endfor %}\n      {% endif %}\n    {% endwith %}\n    {% block content %}{% endblock %}\n  </div>\n</body>\n</html>\n', 'dashboard.html': '{% extends \'base.html\' %}\n{% block title %}Мои траты{% endblock %}\n{% block content %}\n<div class="topbar">\n  <div class="brand" style="margin:0; font-size:20px;">💸 СпендТрекер</div>\n  <div class="hi">{{ username }} · <a href="{{ url_for(\'logout\') }}">выйти</a></div>\n</div>\n\n<div class="stats-grid">\n  <div class="stat"><div class="value">{{ \'%.0f\'|format(today_total) }}</div><div class="label">Сегодня</div></div>\n  <div class="stat"><div class="value">{{ \'%.0f\'|format(week_total) }}</div><div class="label">Неделя</div></div>\n  <div class="stat"><div class="value">{{ \'%.0f\'|format(month_total) }}</div><div class="label">Месяц</div></div>\n</div>\n\n<div class="card">\n  <h3>Добавить трату</h3>\n  <form method="POST">\n    <label>Сумма</label>\n    <input type="text" name="amount" placeholder="Например 350" required autofocus>\n    <label>Категория</label>\n    <select name="category">\n      {% for c in categories %}\n      <option value="{{ c }}">{{ c }}</option>\n      {% endfor %}\n    </select>\n    <label>Дата</label>\n    <input type="date" name="expense_date" value="{{ today }}">\n    <label>Заметка (необязательно)</label>\n    <input type="text" name="note" placeholder="Кофе с другом">\n    <button type="submit">Добавить</button>\n  </form>\n</div>\n\n{% if by_category %}\n<div class="card">\n  <h3>По категориям (месяц)</h3>\n  {% set max_val = by_category.values() | max %}\n  {% for cat, val in by_category.items() | sort(attribute=\'1\', reverse=true) %}\n  <div class="cat-bar">\n    <span style="width:90px;">{{ cat }}</span>\n    <div class="track"><div class="fill" style="width: {{ (val / max_val * 100) | round }}%;"></div></div>\n    <span>{{ \'%.0f\'|format(val) }}</span>\n  </div>\n  {% endfor %}\n</div>\n{% endif %}\n\n<div class="card">\n  <h3>Последние записи</h3>\n  {% if recent %}\n    {% for e in recent %}\n    <div class="expense-row">\n      <div class="info">\n        {{ e.expense_date.strftime(\'%d.%m\') }} — {{ e.note if e.note else e.category }}\n        <div class="cat">{{ e.category }}</div>\n      </div>\n      <div style="display:flex; align-items:center; gap:10px;">\n        <div class="amt">{{ \'%.0f\'|format(e.amount) }} ₽</div>\n        <form method="POST" action="{{ url_for(\'delete_expense\', expense_id=e.id) }}">\n          <button type="submit" class="btn-danger">✕</button>\n        </form>\n      </div>\n    </div>\n    {% endfor %}\n  {% else %}\n    <p style="color: var(--muted); font-size: 14px;">Пока нет записей — добавь первую трату выше.</p>\n  {% endif %}\n</div>\n{% endblock %}\n', 'login.html': '{% extends \'base.html\' %}\n{% block title %}Вход{% endblock %}\n{% block container_class %}center-wrap{% endblock %}\n{% block content %}\n<div class="brand">💸 СпендТрекер</div>\n<div class="card">\n  <h2>Вход</h2>\n  <form method="POST">\n    <label>Логин</label>\n    <input type="text" name="username" required autofocus>\n    <label>Пароль</label>\n    <input type="password" name="password" required>\n    <button type="submit">Войти</button>\n  </form>\n</div>\n<div class="footer-link">Нет аккаунта? <a href="{{ url_for(\'register\') }}">Зарегистрироваться</a></div>\n{% endblock %}\n', 'register.html': '{% extends \'base.html\' %}\n{% block title %}Регистрация{% endblock %}\n{% block container_class %}center-wrap{% endblock %}\n{% block content %}\n<div class="brand">💸 СпендТрекер</div>\n<div class="card">\n  <h2>Регистрация</h2>\n  <form method="POST">\n    <label>Логин</label>\n    <input type="text" name="username" required autofocus>\n    <label>Пароль</label>\n    <input type="password" name="password" required>\n    <button type="submit">Создать аккаунт</button>\n  </form>\n</div>\n<div class="footer-link">Уже есть аккаунт? <a href="{{ url_for(\'login\') }}">Войти</a></div>\n{% endblock %}\n'}
